#define CHECK(expression)                                                            \
  do {                                                                               \
    if (!(expression)) {                                                             \
      std::fprintf(stderr, "%s:%d: CHECK failed: %s\n", __FILE__, __LINE__, #expression); \
      std::abort();                                                                  \
    }                                                                                \
  } while (0)

struct Ev {
  std::uint8_t pitch;
  std::uint8_t velocity;
};

std::uint32_t g_random_seed = 0;
std::uint32_t next_random(void* context) noexcept { return ++*static_cast<std::uint32_t*>(context); }

// Drives one processor instance through a scripted sequence.
struct Harness {
  explicit Harness(const ModuleDescriptor& descriptor) : desc(descriptor) {
    desc.construct(state);
    random.ctx = &g_random_seed;
    random.next = next_random;
  }
  ~Harness() { desc.destroy(state); }
  Harness(const Harness&) = delete;
  Harness& operator=(const Harness&) = delete;

  const ModuleDescriptor& desc;
  GlobalState global{};
  RandomSource random{};
  ModuleState state{};
  NoteBatch last{};

  void seti(std::uint8_t index, std::int32_t value) {
    std::uint8_t effects = 0;
    CHECK(desc.set_param(state, index, ParamValue::integer(value), global, effects));
  }
  void setf(std::uint8_t index, float value) {
    std::uint8_t effects = 0;
    CHECK(desc.set_param(state, index, ParamValue::decimal(value), global, effects));
  }
  void stop() { desc.reset(state, ResetReason::Stop); }
  void step(std::uint32_t now, std::uint32_t tick, std::initializer_list<Ev> ons, std::initializer_list<std::uint8_t> offs) {
    NoteBatch input{};
    for (const Ev& e : ons) CHECK(input.on.append({e.pitch, e.velocity, 0}) == PushResult::Added);
    for (std::uint8_t pitch : offs) CHECK(input.off.append({pitch, 0, 0}) == PushResult::Added);
    TransportView view{true, true, tick, 0};
    ProcessContext context{TimeSample{now, 0}, global, view, random};
    desc.process(state, context, input, last);
  }
};

void expect(const Harness& h, std::initializer_list<Ev> on, std::initializer_list<std::uint8_t> off) {
  CHECK(static_cast<std::size_t>(h.last.on.count) == on.size());
  std::size_t i = 0;
  for (const Ev& e : on) {
    CHECK(h.last.on.items[i].pitch == e.pitch);
    CHECK(h.last.on.items[i].velocity == e.velocity);
    ++i;
  }
  CHECK(static_cast<std::size_t>(h.last.off.count) == off.size());
  i = 0;
  for (std::uint8_t pitch : off) CHECK(h.last.off.items[i++].pitch == pitch);
}

bool equal_name(const char* a, const char* b) noexcept { return std::strcmp(a, b) == 0; }

// Simple MIDI sounding model: note-offs then note-ons per call, as Output submits them.
struct SoundingModel {
  bool sounding[128]{};
  void apply(const NoteBatch& batch) noexcept {
    for (std::uint16_t i = 0; i < batch.off.count; ++i) sounding[batch.off.items[i].pitch] = false;
    for (std::uint16_t i = 0; i < batch.on.count; ++i) sounding[batch.on.items[i].pitch] = true;
  }
  bool any() const noexcept {
    for (bool s : sounding) if (s) return true;
    return false;
  }
};

struct Rng {
  std::uint32_t state;
  std::uint32_t next() noexcept {
    state ^= state << 13U;
    state ^= state >> 17U;
    state ^= state << 5U;
    return state;
  }
  std::uint32_t below(std::uint32_t bound) noexcept { return next() % bound; }
};

